#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with the exact title 'Annual Financial
Report' and the current (operator runtime) date. Only report.pdf is modified.

Strategy: the cover page is generated as a minimal valid PDF using only the
Python standard library. The merge is attempted with any available PDF library
(pypdf/PyPDF2, PyMuPDF, pypdfium2), then with CLI tools (qpdf, pdftk, gs), and
finally with a pure-Python PDF merger. The result is validated by re-parsing.
"""
import datetime
import glob
import io
import os
import re
import shutil
import subprocess
import sys
import tempfile
import zlib

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
WS = b" \t\r\n\0"


def log(msg):
    print(msg, flush=True)


def today_str():
    return datetime.date.today().strftime("%B %d, %Y")


# --------------------------------------------------------------------------
# Minimal PDF generation (standard library only)
# --------------------------------------------------------------------------
def pdf_escape(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def make_cover_content():
    today = today_str()
    W, H = 612.0, 792.0

    def w_est(s, size, factor):
        return len(s) * size * factor

    content = (
        "BT\n"
        "/F1 30 Tf\n"
        f"{((W - w_est(TITLE, 30, 0.55)) / 2.0):.2f} {H / 2.0 + 30:.2f} Td\n"
        f"({pdf_escape(TITLE)}) Tj\n"
        "/F2 16 Tf\n"
        "0 -60 Td\n"
        f"({pdf_escape(today)}) Tj\n"
        "ET\n"
    ).encode("latin-1")
    return content, today


def build_cover_pdf_bytes():
    """Return (bytes, today) of a one-page cover PDF (objects 1..6)."""
    content, today = make_cover_content()
    objects = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>"),
        (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>"),
        (3, (b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
             b"/Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> "
             b"/Contents 4 0 R >>")),
        (4, b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
            + content + b"\nendstream"),
        (5, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"),
        (6, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"),
    ]
    out = bytearray(b"%PDF-1.4\n")
    offsets = {}
    for num, body in objects:
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"
    xref_pos = len(out)
    out += b"xref\n0 7\n"
    out += b"0000000000 65535 f \n"
    for num in range(1, 7):
        out += b"%010d 00000 n \n" % offsets[num]
    out += b"trailer\n<< /Size 7 /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out), today


# --------------------------------------------------------------------------
# Minimal PDF object parser (standard library only)
# --------------------------------------------------------------------------
def skip_ws(data, pos):
    n = len(data)
    while pos < n and data[pos] in WS:
        pos += 1
    return pos


def read_int(data, pos):
    pos = skip_ws(data, pos)
    start = pos
    while pos < len(data) and 48 <= data[pos] <= 57:
        pos += 1
    if pos == start:
        raise ValueError("expected integer")
    return int(data[start:pos]), pos


def read_name(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 1] != b"/":
        raise ValueError("expected name")
    pos += 1
    start = pos
    while pos < len(data) and data[pos] not in WS and data[pos] not in b"[]<>()/{}":
        pos += 1
    return data[start - 1:pos], pos


def parse_value(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise ValueError("unexpected end")
    c = data[pos:pos + 1]
    if c == b"/":
        return read_name(data, pos)
    if c == b"[":
        pos += 1
        arr = []
        while True:
            pos = skip_ws(data, pos)
            if data[pos:pos + 1] == b"]":
                return arr, pos + 1
            v, pos = parse_value(data, pos)
            arr.append(v)
    if c == b"<":
        return parse_dict(data, pos)
    if c == b"(":
        depth = 0
        start = pos
        while pos < len(data):
            ch = data[pos:pos + 1]
            if ch == b"\\":
                pos += 2
                continue
            if ch == b"(":
                depth += 1
            elif ch == b")":
                depth -= 1
                if depth == 0:
                    return data[start:pos + 1], pos + 1
            pos += 1
        raise ValueError("unterminated string")
    m = re.match(rb"(\d+)\s+(\d+)\s+R", data[pos:pos + 64])
    if m:
        pos += m.end()
        return (int(m.group(1)), int(m.group(2))), pos
    m = re.match(rb"(\d+)", data[pos:pos + 64])
    if m:
        pos += m.end()
        return int(m.group(1)), pos
    raise ValueError("unexpected token")


def parse_dict(data, pos):
    if data[pos:pos + 2] != b"<<":
        raise ValueError("expected <<")
    pos += 2
    result = {}
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 2] == b">>":
            return result, pos + 2
        name, pos = read_name(data, pos)
        val, pos = parse_value(data, pos)
        result[name] = val


def read_object(data, offset):
    """Return (num, gen, body_bytes, is_stream). body excludes 'obj'/'endobj'."""
    pos = offset
    num, pos = read_int(data, pos)
    gen, pos = read_int(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise ValueError(f"bad object header at {offset}")
    pos = skip_ws(data, pos + 3)
    body_start = pos
    if data[pos:pos + 2] == b"<<":
        _, pos = parse_dict(data, pos)
        pos = skip_ws(data, pos)
        if data[pos:pos + 6] == b"stream":
            sd = pos + 6
            if data[sd:sd + 2] == b"\r\n":
                sd += 2
            elif data[sd:sd + 1] in (b"\n", b"\r"):
                sd += 1
            end = data.find(b"endstream", sd)
            if end < 0:
                raise ValueError("no endstream")
            body_end = end + len(b"endstream")
            pos2 = skip_ws(data, body_end)
            if data[pos2:pos2 + 6] != b"endobj":
                raise ValueError("no endobj after stream")
            return num, gen, data[body_start:body_end].rstrip(b"\r\n"), True
    end = data.find(b"endobj", pos)
    if end < 0:
        raise ValueError("no endobj")
    return num, gen, data[body_start:end].rstrip(b"\r\n"), False


def find_startxref(data):
    pos = data.rfind(b"startxref")
    if pos < 0:
        raise ValueError("no startxref")
    m = re.search(rb"startxref\s+(\d+)", data[pos:])
    if not m:
        raise ValueError("bad startxref")
    return int(m.group(1))


def parse_classic_xref(data, offset):
    entries = {}
    pos = offset
    if data[pos:pos + 4] != b"xref":
        raise ValueError("not a classic xref")
    pos += 4
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 7] == b"trailer":
            break
        try:
            start, pos = read_int(data, pos)
            count, pos = read_int(data, pos)
        except ValueError:
            break
        for i in range(count):
            pos = skip_ws(data, pos)
            line_end = data.find(b"\n", pos)
            line = data[pos:line_end] if line_end >= 0 else data[pos:pos + 24]
            parts = line.split()
            if len(parts) < 3:
                raise ValueError("bad xref entry")
            off = int(parts[0])
            gen = int(parts[1])
            typ = parts[2]
            if typ == b"n":
                entries[start + i] = (off, gen, b"n")
            else:
                entries[start + i] = (0, gen, b"f")
            pos = line_end + 1 if line_end >= 0 else pos + 24
    return entries, pos


def parse_trailer(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise ValueError("no trailer")
    pos = skip_ws(data, pos + 7)
    return parse_dict(data, pos)


def parse_xref_stream(data, offset):
    num, gen, body, is_stream = read_object(data, offset)
    if not is_stream:
        raise ValueError("expected xref stream")
    d, _ = parse_dict(body, 0)
    W = d.get(b"/W")
    size = d.get(b"/Size")
    if not isinstance(W, list) or len(W) != 3:
        raise ValueError("bad /W in xref stream")
    index = d.get(b"/Index") or [0, size]
    si = body.find(b"stream")
    sd = si + 6
    if body[sd:sd + 2] == b"\r\n":
        sd += 2
    elif body[sd:sd + 1] in (b"\n", b"\r"):
        sd += 1
    end = body.find(b"endstream", sd)
    raw = body[sd:end] if end >= 0 else body[sd:]
    sdata = zlib.decompress(raw)
    w1, w2, w3 = W
    rlen = w1 + w2 + w3
    entries = {}
    base = 0
    for i in range(0, len(index), 2):
        start, count = index[i], index[i + 1]
        for j in range(count):
            rec = sdata[base + j * rlen: base + (j + 1) * rlen]

            def fld(o, w):
                return int.from_bytes(rec[o:o + w], "big") if w > 0 else 0

            typ = fld(0, w1)
            f2 = fld(w1, w2)
            f3 = fld(w1 + w2, w3)
            if typ == 1:
                entries[start + j] = (f2, f3, b"n")
            elif typ == 2:
                entries[start + j] = (None, (f2, f3), b"c")
            else:
                entries[start + j] = (0, 0, b"f")
        base += count * rlen
    return entries, d


def parse_pdf(data):
    xref_off = find_startxref(data)
    entries = {}
    trailer = {}
    off = xref_off
    while off is not None:
        if data[off:off + 4] == b"xref":
            e, pos = parse_classic_xref(data, off)
            tr = parse_trailer(data, pos)
        else:
            e, tr = parse_xref_stream(data, off)
        for k, v in e.items():
            if k not in entries:
                entries[k] = v
        if not trailer:
            trailer = tr
        prev = tr.get(b"/Prev")
        off = int(prev) if prev else None
    root_ref = trailer.get(b"/Root")
    if not isinstance(root_ref, tuple):
        raise ValueError("no /Root in trailer")
    root_num = root_ref[0]
    re_ = entries.get(root_num)
    if not re_ or re_[2] != b"n":
        raise ValueError("catalog object not readable")
    rn, rg, rbody, ris = read_object(data, re_[0])
    cat, _ = parse_dict(rbody, 0)
    pages_ref = cat.get(b"/Pages")
    if not isinstance(pages_ref, tuple):
        raise ValueError("no /Pages in catalog")
    pages_num = pages_ref[0]
    return {
        "entries": entries,
        "trailer": trailer,
        "root_num": root_num,
        "pages_num": pages_num,
    }


def count_pages(data, entries, pages_num):
    seen = set()

    def walk(num):
        if num in seen:
            return 0
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return 0
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return 1
        kids = d.get(b"/Kids")
        if not isinstance(kids, list):
            return 0
        total = 0
        for kid in kids:
            if isinstance(kid, tuple):
                total += walk(kid[0])
        return total

    return walk(pages_num)


def first_page_num(data, entries, pages_num):
    seen = set()
    num = pages_num
    while True:
        if num in seen:
            return None
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return None
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return num
        kids = d.get(b"/Kids")
        if not isinstance(kids, list) or not kids:
            return None
        first = kids[0]
        if not isinstance(first, tuple):
            return None
        num = first[0]


def extract_page_text(data, entries, page_num):
    e = entries.get(page_num)
    if not e or e[2] != b"n":
        return ""
    n, g, body, is_stream = read_object(data, e[0])
    d, _ = parse_dict(body, 0)
    contents = d.get(b"/Contents")
    refs = []
    if isinstance(contents, tuple):
        refs.append(contents)
    elif isinstance(contents, list):
        refs = [c for c in contents if isinstance(c, tuple)]
    parts = []
    for ref in refs:
        ce = entries.get(ref[0])
        if not ce or ce[2] != b"n":
            continue
        cn, cg, cbody, cis = read_object(data, ce[0])
        si = cbody.find(b"stream")
        if si < 0:
            continue
        sd = si + 6
        if cbody[sd:sd + 2] == b"\r\n":
            sd += 2
        elif cbody[sd:sd + 1] in (b"\n", b"\r"):
            sd += 1
        end = cbody.find(b"endstream", sd)
        raw = cbody[sd:end] if end >= 0 else cbody[sd:]
        if raw[:2] == b"\x78\x9c":
            try:
                raw = zlib.decompress(raw)
            except Exception:
                pass
        parts.append(raw.decode("latin-1", "replace"))
    return "\n".join(parts)


# --------------------------------------------------------------------------
# Library / tool detection
# --------------------------------------------------------------------------
def import_pdf_libs():
    libs = {}
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    for pat in (".codex/skills/pdf/**/site-packages",
                ".codex/skills/pdf/**/dist-packages"):
        for sp in sorted(glob.glob(pat, recursive=True)):
            if sp not in sys.path:
                sys.path.insert(0, sp)
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    try:
        import fitz
        libs["fitz"] = fitz
        return libs
    except Exception:
        pass
    try:
        import pypdfium2 as pdfium
        libs["pdfium"] = pdfium
        return libs
    except Exception:
        pass
    return libs


# --------------------------------------------------------------------------
# Merge strategies
# --------------------------------------------------------------------------
def merge_with_pypdf(cover_bytes, PdfReader, PdfWriter):
    reader = PdfReader(io.BytesIO(cover_bytes))
    writer = PdfWriter()
    writer.add_page(reader.pages[0])
    rep = PdfReader(REPORT)
    for p in rep.pages:
        writer.add_page(p)
    with open(REPORT, "wb") as fh:
        writer.write(fh)
    log("merged via pypdf")


def merge_with_fitz(cover_bytes, fitz):
    cover = fitz.open(stream=cover_bytes, filetype="pdf")
    doc = fitz.open(REPORT)
    doc.insert_pdf(cover, start_at=0)
    data = doc.tobytes(garbage=3, deflate=True)
    doc.close()
    cover.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via PyMuPDF")


def merge_with_pdfium(cover_bytes, pdfium):
    cover = pdfium.PdfDocument.new(cover_bytes)
    doc = pdfium.PdfDocument(REPORT)
    cover.import_pages(doc, pages=list(range(len(doc))), index=1)
    data = cover.tobytes()
    cover.close()
    doc.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via pypdfium2")


def merge_with_cli(cover_bytes, tool_name, argv_builder):
    tmpdir = tempfile.mkdtemp(prefix="cover_task_")
    try:
        cover_path = os.path.join(tmpdir, "cover.pdf")
        out_path = os.path.join(tmpdir, "out.pdf")
        with open(cover_path, "wb") as fh:
            fh.write(cover_bytes)
        cmd = argv_builder(cover_path, out_path)
        proc = subprocess.run(cmd, capture_output=True, text=True)
        if proc.returncode != 0:
            raise RuntimeError(f"{tool_name} failed: {proc.stderr or proc.stdout}")
        if not os.path.exists(out_path):
            raise RuntimeError(f"{tool_name} produced no output")
        os.replace(out_path, REPORT)
        log(f"merged via {tool_name}")
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


def merge_pure_python(data, cover_bytes):
    info = parse_pdf(data)
    entries = info["entries"]
    trailer = info["trailer"]
    root_num = info["root_num"]
    pages_num = info["pages_num"]
    if b"/Encrypt" in trailer:
        raise RuntimeError("encrypted PDF cannot be merged with pure-Python merger")
    pe = entries.get(pages_num)
    if not pe or pe[2] != b"n":
        raise RuntimeError("pages object is compressed; pure-Python merger unsupported")
    pn, pg, pbody, pis = read_object(data, pe[0])
    if pis:
        raise RuntimeError("pages object is a stream; pure-Python merger unsupported")
    pd, _ = parse_dict(pbody, 0)
    kids = pd.get(b"/Kids") or []
    count = pd.get(b"/Count")
    if count is None:
        count = len([k for k in kids if isinstance(k, tuple)])
    m = re.search(rb"/Kids\s*\[(.*?)\]", pbody, re.S)
    kids_raw = m.group(1).strip() if m else b""
    max_num = max(entries) if entries else 0
    my_page = max_num + 1
    my_contents = max_num + 2
    my_font1 = max_num + 3
    my_font2 = max_num + 4
    new_size = my_font2 + 1

    content, today = make_cover_content()
    my_page_body = (b"<< /Type /Page /Parent %d 0 R /MediaBox [0 0 612 792] "
                    b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                    b"/Contents %d 0 R >>") % (pages_num, my_font1, my_font2, my_contents)
    my_contents_body = (b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
                        + content + b"\nendstream")
    my_font1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"
    my_font2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"

    new_kids = b"%d 0 R " % my_page
    if kids_raw:
        new_kids += kids_raw
    new_pbody = re.sub(rb"/Kids\s*\[.*?\]", b"/Kids [" + new_kids + b"]",
                       pbody, count=1, flags=re.S)
    new_pbody = re.sub(rb"/Count\s+\d+", b"/Count %d" % (count + 1),
                       new_pbody, count=1)

    out = bytearray(b"%PDF-1.4\n")
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"

    emit(my_page, my_page_body)
    emit(my_contents, my_contents_body)
    emit(my_font1, my_font1_body)
    emit(my_font2, my_font2_body)
    emit(pages_num, new_pbody)
    for num in sorted(entries):
        if num in (my_page, my_contents, my_font1, my_font2) or num == pages_num:
            continue
        off_, gen, typ = entries[num]
        if typ != b"n" or off_ is None:
            continue
        n2, g2, body2, is_stream2 = read_object(data, off_)
        emit(num, body2)

    xref_pos = len(out)
    out += b"xref\n0 %d\n" % new_size
    out += b"0000000000 65535 f \n"
    for num in range(1, new_size):
        if num in offsets:
            out += b"%010d 00000 n \n" % offsets[num]
        else:
            out += b"%010d 65535 f \n" % 0
    trailer_out = b"<< /Size %d /Root %d 0 R" % (new_size, root_num)
    info_ref = trailer.get(b"/Info")
    if isinstance(info_ref, tuple):
        trailer_out += b" /Info %d %d R" % info_ref
    trailer_out += b" >>"
    out += b"trailer\n" + trailer_out + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    with open(REPORT, "wb") as fh:
        fh.write(bytes(out))
    log("merged via pure-Python PDF merger")


# --------------------------------------------------------------------------
# Main
# --------------------------------------------------------------------------
def main():
    if not os.path.exists(REPORT):
        log(f"error: {REPORT} not found in {os.getcwd()}")
        return 1

    cover_bytes, today = build_cover_pdf_bytes()
    try:
        parse_pdf(cover_bytes)
    except Exception as exc:
        log(f"error: generated cover page failed self-check: {exc}")
        return 1
    log(f"cover page built for date '{today}'")

    original = open(REPORT, "rb").read()
    old_count = None
    try:
        info0 = parse_pdf(original)
        old_count = count_pages(original, info0["entries"], info0["pages_num"])
        log(f"report.pdf: {old_count} page(s) before change")
    except Exception as exc:
        log(f"note: stdlib pre-parse unavailable ({exc})")

    libs = import_pdf_libs()
    merged = False
    if "pypdf" in libs:
        try:
            merge_with_pypdf(cover_bytes, libs["pypdf"][0], libs["pypdf"][1])
            merged = True
        except Exception as exc:
            log(f"pypdf merge failed: {exc}")
    if not merged and "fitz" in libs:
        try:
            merge_with_fitz(cover_bytes, libs["fitz"])
            merged = True
        except Exception as exc:
            log(f"PyMuPDF merge failed: {exc}")
    if not merged and "pdfium" in libs:
        try:
            merge_with_pdfium(cover_bytes, libs["pdfium"])
            merged = True
        except Exception as exc:
            log(f"pypdfium2 merge failed: {exc}")
    if not merged and shutil.which("qpdf"):
        try:
            merge_with_cli(cover_bytes, "qpdf",
                           lambda c, o: ["qpdf", "--empty", "--pages", c, REPORT, "--", o])
            merged = True
        except Exception as exc:
            log(f"qpdf merge failed: {exc}")
    if not merged and shutil.which("pdftk"):
        try:
            merge_with_cli(cover_bytes, "pdftk",
                           lambda c, o: ["pdftk", c, REPORT, "cat", "output", o])
            merged = True
        except Exception as exc:
            log(f"pdftk merge failed: {exc}")
    if not merged and shutil.which("gs"):
        try:
            merge_with_cli(cover_bytes, "gs",
                           lambda c, o: ["gs", "-q", "-dNOPAUSE", "-dBATCH",
                                         "-sDEVICE=pdfwrite",
                                         "-sOutputFile=" + o, c, REPORT])
            merged = True
        except Exception as exc:
            log(f"gs merge failed: {exc}")
    if not merged:
        try:
            merge_pure_python(original, cover_bytes)
            merged = True
        except Exception as exc:
            log(f"pure-Python merge failed: {exc}")

    if not merged:
        log("error: no merge strategy succeeded")
        return 1

    # ---------------- validation ----------------
    data = open(REPORT, "rb").read()
    ok = False
    if "pypdf" in libs:
        try:
            PdfReader = libs["pypdf"][0]
            reader = PdfReader(REPORT)
            total = len(reader.pages)
            t = reader.pages[0].extract_text() or ""
            ok_title = TITLE in t
            ok_date = today in t
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (pypdf): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            log(f"pypdf validation failed: {exc}")
    if not ok:
        try:
            info = parse_pdf(data)
            total = count_pages(data, info["entries"], info["pages_num"])
            fp = first_page_num(data, info["entries"], info["pages_num"])
            text = extract_page_text(data, info["entries"], fp) if fp else ""
            ok_title = TITLE in text
            ok_date = today in text
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (stdlib): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            log(f"stdlib validation failed: {exc}")

    if not ok:
        log("error: cover page validation failed")
        return 1
    log("OK: cover page prepended to report.pdf")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with the exact title 'Annual Financial
Report' and the current (operator runtime) date. Only report.pdf is modified.

Strategy: the cover page is generated as a minimal valid PDF using only the
Python standard library. The merge is attempted with any available PDF library
(pypdf/PyPDF2, PyMuPDF, pypdfium2), then with CLI tools (qpdf, pdftk, gs), and
finally with a pure-Python PDF merger. The result is validated by re-parsing.
"""
import datetime
import glob
import io
import os
import re
import shutil
import subprocess
import sys
import tempfile
import traceback
import zlib

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
WS = b" \t\r\n\0"


def log(msg):
    print(msg, flush=True)


def today_str():
    return datetime.date.today().strftime("%B %d, %Y")


# --------------------------------------------------------------------------
# Minimal PDF generation (standard library only)
# --------------------------------------------------------------------------
def pdf_escape(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def make_cover_content():
    today = today_str()
    W, H = 612.0, 792.0

    def w_est(s, size, factor):
        return len(s) * size * factor

    content = (
        "BT\n"
        "/F1 30 Tf\n"
        f"{((W - w_est(TITLE, 30, 0.55)) / 2.0):.2f} {H / 2.0 + 30:.2f} Td\n"
        f"({pdf_escape(TITLE)}) Tj\n"
        "/F2 16 Tf\n"
        "0 -60 Td\n"
        f"({pdf_escape(today)}) Tj\n"
        "ET\n"
    ).encode("latin-1")
    return content, today


def build_cover_pdf_bytes():
    """Return (bytes, today) of a one-page cover PDF (objects 1..6)."""
    content, today = make_cover_content()
    objects = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>"),
        (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>"),
        (3, (b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
             b"/Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> "
             b"/Contents 4 0 R >>")),
        (4, b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
            + content + b"\nendstream"),
        (5, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"),
        (6, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"),
    ]
    out = bytearray(b"%PDF-1.4\n")
    offsets = {}
    for num, body in objects:
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"
    xref_pos = len(out)
    out += b"xref\n0 7\n"
    out += b"0000000000 65535 f \n"
    for num in range(1, 7):
        out += b"%010d 00000 n \n" % offsets[num]
    out += b"trailer\n<< /Size 7 /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out), today


# --------------------------------------------------------------------------
# Minimal PDF object parser (standard library only)
# --------------------------------------------------------------------------
def skip_ws(data, pos):
    n = len(data)
    while pos < n and data[pos] in WS:
        pos += 1
    return pos


def read_int(data, pos):
    pos = skip_ws(data, pos)
    start = pos
    while pos < len(data) and 48 <= data[pos] <= 57:
        pos += 1
    if pos == start:
        raise ValueError("expected integer")
    return int(data[start:pos]), pos


def read_name(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 1] != b"/":
        raise ValueError("expected name")
    pos += 1
    start = pos
    while pos < len(data) and data[pos] not in WS and data[pos] not in b"[]<>()/{}":
        pos += 1
    return data[start - 1:pos], pos


def parse_value(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise ValueError("unexpected end")
    c = data[pos:pos + 1]
    if c == b"/":
        return read_name(data, pos)
    if c == b"[":
        pos += 1
        arr = []
        while True:
            pos = skip_ws(data, pos)
            if data[pos:pos + 1] == b"]":
                return arr, pos + 1
            v, pos = parse_value(data, pos)
            arr.append(v)
    if c == b"<":
        return parse_dict(data, pos)
    if c == b"(":
        depth = 0
        start = pos
        while pos < len(data):
            ch = data[pos:pos + 1]
            if ch == b"\\":
                pos += 2
                continue
            if ch == b"(":
                depth += 1
            elif ch == b")":
                depth -= 1
                if depth == 0:
                    return data[start:pos + 1], pos + 1
            pos += 1
        raise ValueError("unterminated string")
    m = re.match(rb"(\d+)\s+(\d+)\s+R", data[pos:pos + 64])
    if m:
        pos += m.end()
        return (int(m.group(1)), int(m.group(2))), pos
    m = re.match(rb"(\d+)", data[pos:pos + 64])
    if m:
        pos += m.end()
        return int(m.group(1)), pos
    raise ValueError("unexpected token")


def parse_dict(data, pos):
    if data[pos:pos + 2] != b"<<":
        raise ValueError("expected <<")
    pos += 2
    result = {}
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 2] == b">>":
            return result, pos + 2
        name, pos = read_name(data, pos)
        val, pos = parse_value(data, pos)
        result[name] = val


def read_object(data, offset):
    """Return (num, gen, body_bytes, is_stream). body excludes 'obj'/'endobj'."""
    pos = offset
    num, pos = read_int(data, pos)
    gen, pos = read_int(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise ValueError(f"bad object header at {offset}")
    pos = skip_ws(data, pos + 3)
    body_start = pos
    if data[pos:pos + 2] == b"<<":
        _, pos = parse_dict(data, pos)
        pos = skip_ws(data, pos)
        if data[pos:pos + 6] == b"stream":
            sd = pos + 6
            if data[sd:sd + 2] == b"\r\n":
                sd += 2
            elif data[sd:sd + 1] in (b"\n", b"\r"):
                sd += 1
            end = data.find(b"endstream", sd)
            if end < 0:
                raise ValueError("no endstream")
            body_end = end + len(b"endstream")
            pos2 = skip_ws(data, body_end)
            if data[pos2:pos2 + 6] != b"endobj":
                raise ValueError("no endobj after stream")
            return num, gen, data[body_start:body_end].rstrip(b"\r\n"), True
    end = data.find(b"endobj", pos)
    if end < 0:
        raise ValueError("no endobj")
    return num, gen, data[body_start:end].rstrip(b"\r\n"), False


def find_startxref(data):
    pos = data.rfind(b"startxref")
    if pos < 0:
        raise ValueError("no startxref")
    m = re.search(rb"startxref\s+(\d+)", data[pos:])
    if not m:
        raise ValueError("bad startxref")
    return int(m.group(1))


def parse_classic_xref(data, offset):
    entries = {}
    pos = offset
    if data[pos:pos + 4] != b"xref":
        raise ValueError("not a classic xref")
    pos += 4
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 7] == b"trailer":
            break
        try:
            start, pos = read_int(data, pos)
            count, pos = read_int(data, pos)
        except ValueError:
            break
        for i in range(count):
            pos = skip_ws(data, pos)
            line_end = data.find(b"\n", pos)
            line = data[pos:line_end] if line_end >= 0 else data[pos:pos + 24]
            parts = line.split()
            if len(parts) < 3:
                raise ValueError("bad xref entry")
            off = int(parts[0])
            gen = int(parts[1])
            typ = parts[2]
            if typ == b"n":
                entries[start + i] = (off, gen, b"n")
            else:
                entries[start + i] = (0, gen, b"f")
            pos = line_end + 1 if line_end >= 0 else pos + 24
    return entries, pos


def parse_trailer(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise ValueError("no trailer")
    pos = skip_ws(data, pos + 7)
    return parse_dict(data, pos)


def parse_xref_stream(data, offset):
    num, gen, body, is_stream = read_object(data, offset)
    if not is_stream:
        raise ValueError("expected xref stream")
    d, _ = parse_dict(body, 0)
    W = d.get(b"/W")
    size = d.get(b"/Size")
    if not isinstance(W, list) or len(W) != 3:
        raise ValueError("bad /W in xref stream")
    index = d.get(b"/Index") or [0, size]
    si = body.find(b"stream")
    sd = si + 6
    if body[sd:sd + 2] == b"\r\n":
        sd += 2
    elif body[sd:sd + 1] in (b"\n", b"\r"):
        sd += 1
    end = body.find(b"endstream", sd)
    raw = body[sd:end] if end >= 0 else body[sd:]
    sdata = zlib.decompress(raw)
    w1, w2, w3 = W
    rlen = w1 + w2 + w3
    entries = {}
    base = 0
    for i in range(0, len(index), 2):
        start, count = index[i], index[i + 1]
        for j in range(count):
            rec = sdata[base + j * rlen: base + (j + 1) * rlen]

            def fld(o, w):
                return int.from_bytes(rec[o:o + w], "big") if w > 0 else 0

            typ = fld(0, w1)
            f2 = fld(w1, w2)
            f3 = fld(w1 + w2, w3)
            if typ == 1:
                entries[start + j] = (f2, f3, b"n")
            elif typ == 2:
                entries[start + j] = (None, (f2, f3), b"c")
            else:
                entries[start + j] = (0, 0, b"f")
        base += count * rlen
    return entries, d


def parse_pdf(data):
    xref_off = find_startxref(data)
    entries = {}
    trailer = {}
    off = xref_off
    while off is not None:
        if data[off:off + 4] == b"xref":
            e, pos = parse_classic_xref(data, off)
            tr = parse_trailer(data, pos)
        else:
            e, tr = parse_xref_stream(data, off)
        for k, v in e.items():
            if k not in entries:
                entries[k] = v
        if not trailer:
            trailer = tr
        prev = tr.get(b"/Prev")
        off = int(prev) if prev else None
    root_ref = trailer.get(b"/Root")
    if not isinstance(root_ref, tuple):
        raise ValueError("no /Root in trailer")
    root_num = root_ref[0]
    re_ = entries.get(root_num)
    if not re_ or re_[2] != b"n":
        raise ValueError("catalog object not readable")
    rn, rg, rbody, ris = read_object(data, re_[0])
    cat, _ = parse_dict(rbody, 0)
    pages_ref = cat.get(b"/Pages")
    if not isinstance(pages_ref, tuple):
        raise ValueError("no /Pages in catalog")
    pages_num = pages_ref[0]
    return {
        "entries": entries,
        "trailer": trailer,
        "root_num": root_num,
        "pages_num": pages_num,
    }


def count_pages(data, entries, pages_num):
    seen = set()

    def walk(num):
        if num in seen:
            return 0
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return 0
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return 1
        kids = d.get(b"/Kids")
        if not isinstance(kids, list):
            return 0
        total = 0
        for kid in kids:
            if isinstance(kid, tuple):
                total += walk(kid[0])
        return total

    return walk(pages_num)


def first_page_num(data, entries, pages_num):
    seen = set()
    num = pages_num
    while True:
        if num in seen:
            return None
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return None
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return num
        kids = d.get(b"/Kids")
        if not isinstance(kids, list) or not kids:
            return None
        first = kids[0]
        if not isinstance(first, tuple):
            return None
        num = first[0]


def extract_page_text(data, entries, page_num):
    e = entries.get(page_num)
    if not e or e[2] != b"n":
        return ""
    n, g, body, is_stream = read_object(data, e[0])
    d, _ = parse_dict(body, 0)
    contents = d.get(b"/Contents")
    refs = []
    if isinstance(contents, tuple):
        refs.append(contents)
    elif isinstance(contents, list):
        refs = [c for c in contents if isinstance(c, tuple)]
    parts = []
    for ref in refs:
        ce = entries.get(ref[0])
        if not ce or ce[2] != b"n":
            continue
        cn, cg, cbody, cis = read_object(data, ce[0])
        si = cbody.find(b"stream")
        if si < 0:
            continue
        sd = si + 6
        if cbody[sd:sd + 2] == b"\r\n":
            sd += 2
        elif cbody[sd:sd + 1] in (b"\n", b"\r"):
            sd += 1
        end = cbody.find(b"endstream", sd)
        raw = cbody[sd:end] if end >= 0 else cbody[sd:]
        if raw[:2] == b"\x78\x9c":
            try:
                raw = zlib.decompress(raw)
            except Exception:
                pass
        parts.append(raw.decode("latin-1", "replace"))
    return "\n".join(parts)


# --------------------------------------------------------------------------
# Library / tool detection
# --------------------------------------------------------------------------
def import_pdf_libs():
    libs = {}
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    for pat in (".codex/skills/pdf/**/site-packages",
                ".codex/skills/pdf/**/dist-packages"):
        for sp in sorted(glob.glob(pat, recursive=True)):
            if sp not in sys.path:
                sys.path.insert(0, sp)
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    try:
        import fitz
        libs["fitz"] = fitz
        return libs
    except Exception:
        pass
    try:
        import pypdfium2 as pdfium
        libs["pdfium"] = pdfium
        return libs
    except Exception:
        pass
    return libs


# --------------------------------------------------------------------------
# Merge strategies
# --------------------------------------------------------------------------
def merge_with_pypdf(cover_bytes, PdfReader, PdfWriter):
    reader = PdfReader(io.BytesIO(cover_bytes))
    writer = PdfWriter()
    writer.add_page(reader.pages[0])
    rep = PdfReader(REPORT)
    for p in rep.pages:
        writer.add_page(p)
    with open(REPORT, "wb") as fh:
        writer.write(fh)
    log("merged via pypdf")


def merge_with_fitz(cover_bytes, fitz):
    cover = fitz.open(stream=cover_bytes, filetype="pdf")
    doc = fitz.open(REPORT)
    doc.insert_pdf(cover, start_at=0)
    data = doc.tobytes(garbage=3, deflate=True)
    doc.close()
    cover.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via PyMuPDF")


def merge_with_pdfium(cover_bytes, pdfium):
    cover = pdfium.PdfDocument.new(cover_bytes)
    doc = pdfium.PdfDocument(REPORT)
    cover.import_pages(doc, pages=list(range(len(doc))), index=1)
    data = cover.tobytes()
    cover.close()
    doc.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via pypdfium2")


def merge_with_cli(cover_bytes, tool_name, argv_builder):
    tmpdir = tempfile.mkdtemp(prefix="cover_task_")
    try:
        cover_path = os.path.join(tmpdir, "cover.pdf")
        out_path = os.path.join(tmpdir, "out.pdf")
        with open(cover_path, "wb") as fh:
            fh.write(cover_bytes)
        cmd = argv_builder(cover_path, out_path)
        proc = subprocess.run(cmd, capture_output=True, text=True)
        if proc.returncode != 0:
            raise RuntimeError(f"{tool_name} failed: {proc.stderr or proc.stdout}")
        if not os.path.exists(out_path):
            raise RuntimeError(f"{tool_name} produced no output")
        os.replace(out_path, REPORT)
        log(f"merged via {tool_name}")
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


def merge_pure_python(data, cover_bytes):
    info = parse_pdf(data)
    entries = info["entries"]
    trailer = info["trailer"]
    root_num = info["root_num"]
    pages_num = info["pages_num"]
    if b"/Encrypt" in trailer:
        raise RuntimeError("encrypted PDF cannot be merged with pure-Python merger")
    pe = entries.get(pages_num)
    if not pe or pe[2] != b"n":
        raise RuntimeError("pages object is compressed; pure-Python merger unsupported")
    pn, pg, pbody, pis = read_object(data, pe[0])
    if pis:
        raise RuntimeError("pages object is a stream; pure-Python merger unsupported")
    pd, _ = parse_dict(pbody, 0)
    kids = pd.get(b"/Kids") or []
    count = pd.get(b"/Count")
    if count is None:
        count = len([k for k in kids if isinstance(k, tuple)])
    m = re.search(rb"/Kids\s*\[(.*?)\]", pbody, re.S)
    kids_raw = m.group(1).strip() if m else b""
    max_num = max(entries) if entries else 0
    my_page = max_num + 1
    my_contents = max_num + 2
    my_font1 = max_num + 3
    my_font2 = max_num + 4
    new_size = my_font2 + 1

    content, today = make_cover_content()
    my_page_body = (b"<< /Type /Page /Parent %d 0 R /MediaBox [0 0 612 792] "
                    b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                    b"/Contents %d 0 R >>") % (pages_num, my_font1, my_font2, my_contents)
    my_contents_body = (b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
                        + content + b"\nendstream")
    my_font1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"
    my_font2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"

    new_kids = b"%d 0 R " % my_page
    if kids_raw:
        new_kids += kids_raw
    new_pbody = re.sub(rb"/Kids\s*\[.*?\]", b"/Kids [" + new_kids + b"]",
                       pbody, count=1, flags=re.S)
    new_pbody = re.sub(rb"/Count\s+\d+", b"/Count %d" % (count + 1),
                       new_pbody, count=1)

    out = bytearray(b"%PDF-1.4\n")
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"

    emit(my_page, my_page_body)
    emit(my_contents, my_contents_body)
    emit(my_font1, my_font1_body)
    emit(my_font2, my_font2_body)
    emit(pages_num, new_pbody)
    for num in sorted(entries):
        if num in (my_page, my_contents, my_font1, my_font2) or num == pages_num:
            continue
        off_, gen, typ = entries[num]
        if typ != b"n" or off_ is None:
            continue
        n2, g2, body2, is_stream2 = read_object(data, off_)
        emit(num, body2)

    xref_pos = len(out)
    out += b"xref\n0 %d\n" % new_size
    out += b"0000000000 65535 f \n"
    for num in range(1, new_size):
        if num in offsets:
            out += b"%010d 00000 n \n" % offsets[num]
        else:
            out += b"%010d 65535 f \n" % 0
    trailer_out = b"<< /Size %d /Root %d 0 R" % (new_size, root_num)
    info_ref = trailer.get(b"/Info")
    if isinstance(info_ref, tuple):
        trailer_out += b" /Info %d %d R" % info_ref
    trailer_out += b" >>"
    out += b"trailer\n" + trailer_out + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    with open(REPORT, "wb") as fh:
        fh.write(bytes(out))
    log("merged via pure-Python PDF merger")


# --------------------------------------------------------------------------
# Main
# --------------------------------------------------------------------------
def main():
    if not os.path.exists(REPORT):
        log(f"error: {REPORT} not found in {os.getcwd()}")
        return 1

    cover_bytes, today = build_cover_pdf_bytes()
    try:
        parse_pdf(cover_bytes)
    except Exception as exc:
        traceback.print_exc()
        log(f"error: generated cover page failed self-check: {exc}")
        return 1
    log(f"cover page built for date '{today}'")

    original = open(REPORT, "rb").read()
    old_count = None
    try:
        info0 = parse_pdf(original)
        old_count = count_pages(original, info0["entries"], info0["pages_num"])
        log(f"report.pdf: {old_count} page(s) before change")
    except Exception as exc:
        log(f"note: stdlib pre-parse unavailable ({exc})")

    libs = import_pdf_libs()
    merged = False
    if "pypdf" in libs:
        try:
            merge_with_pypdf(cover_bytes, libs["pypdf"][0], libs["pypdf"][1])
            merged = True
        except Exception as exc:
            log(f"pypdf merge failed: {exc}")
    if not merged and "fitz" in libs:
        try:
            merge_with_fitz(cover_bytes, libs["fitz"])
            merged = True
        except Exception as exc:
            log(f"PyMuPDF merge failed: {exc}")
    if not merged and "pdfium" in libs:
        try:
            merge_with_pdfium(cover_bytes, libs["pdfium"])
            merged = True
        except Exception as exc:
            log(f"pypdfium2 merge failed: {exc}")
    if not merged and shutil.which("qpdf"):
        try:
            merge_with_cli(cover_bytes, "qpdf",
                           lambda c, o: ["qpdf", "--empty", "--pages", c, REPORT, "--", o])
            merged = True
        except Exception as exc:
            log(f"qpdf merge failed: {exc}")
    if not merged and shutil.which("pdftk"):
        try:
            merge_with_cli(cover_bytes, "pdftk",
                           lambda c, o: ["pdftk", c, REPORT, "cat", "output", o])
            merged = True
        except Exception as exc:
            log(f"pdftk merge failed: {exc}")
    if not merged and shutil.which("gs"):
        try:
            merge_with_cli(cover_bytes, "gs",
                           lambda c, o: ["gs", "-q", "-dNOPAUSE", "-dBATCH",
                                         "-sDEVICE=pdfwrite",
                                         "-sOutputFile=" + o, c, REPORT])
            merged = True
        except Exception as exc:
            log(f"gs merge failed: {exc}")
    if not merged:
        try:
            merge_pure_python(original, cover_bytes)
            merged = True
        except Exception as exc:
            log(f"pure-Python merge failed: {exc}")

    if not merged:
        log("error: no merge strategy succeeded")
        return 1

    # ---------------- validation ----------------
    data = open(REPORT, "rb").read()
    ok = False
    if "pypdf" in libs:
        try:
            PdfReader = libs["pypdf"][0]
            reader = PdfReader(REPORT)
            total = len(reader.pages)
            t = reader.pages[0].extract_text() or ""
            ok_title = TITLE in t
            ok_date = today in t
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (pypdf): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            log(f"pypdf validation failed: {exc}")
    if not ok:
        try:
            info = parse_pdf(data)
            total = count_pages(data, info["entries"], info["pages_num"])
            fp = first_page_num(data, info["entries"], info["pages_num"])
            text = extract_page_text(data, info["entries"], fp) if fp else ""
            ok_title = TITLE in text
            ok_date = today in text
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (stdlib): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            traceback.print_exc()
            log(f"stdlib validation failed: {exc}")

    if not ok:
        log("error: cover page validation failed")
        return 1
    log("OK: cover page prepended to report.pdf")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with the exact title 'Annual Financial
Report' and the current (operator runtime) date. Only report.pdf is modified.

Strategy: the cover page is generated as a minimal valid PDF using only the
Python standard library. The merge is attempted with any available PDF library
(pypdf/PyPDF2, PyMuPDF, pypdfium2), then with CLI tools (qpdf, pdftk, gs), and
finally with a pure-Python PDF merger. The result is validated by re-parsing.
"""
import datetime
import glob
import io
import os
import re
import shutil
import subprocess
import sys
import tempfile
import zlib

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
WS = b" \t\r\n\0"


def log(msg):
    print(msg, flush=True)


def today_str():
    return datetime.date.today().strftime("%B %d, %Y")


# --------------------------------------------------------------------------
# Minimal PDF generation (standard library only)
# --------------------------------------------------------------------------
def pdf_escape(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def make_cover_content():
    today = today_str()
    W, H = 612.0, 792.0

    def w_est(s, size, factor):
        return len(s) * size * factor

    content = (
        "BT\n"
        "/F1 30 Tf\n"
        f"{((W - w_est(TITLE, 30, 0.55)) / 2.0):.2f} {H / 2.0 + 30:.2f} Td\n"
        f"({pdf_escape(TITLE)}) Tj\n"
        "/F2 16 Tf\n"
        "0 -60 Td\n"
        f"({pdf_escape(today)}) Tj\n"
        "ET\n"
    ).encode("latin-1")
    return content, today


def build_cover_pdf_bytes():
    """Return (bytes, today) of a one-page cover PDF (objects 1..6)."""
    content, today = make_cover_content()
    objects = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>"),
        (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>"),
        (3, (b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
             b"/Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> "
             b"/Contents 4 0 R >>")),
        (4, b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
            + content + b"\nendstream"),
        (5, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"),
        (6, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"),
    ]
    out = bytearray(b"%PDF-1.4\n")
    offsets = {}
    for num, body in objects:
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"
    xref_pos = len(out)
    out += b"xref\n0 7\n"
    out += b"0000000000 65535 f \n"
    for num in range(1, 7):
        out += b"%010d 00000 n \n" % offsets[num]
    out += b"trailer\n<< /Size 7 /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out), today


# --------------------------------------------------------------------------
# Minimal PDF object parser (standard library only)
# --------------------------------------------------------------------------
def skip_ws(data, pos):
    n = len(data)
    while pos < n and data[pos] in WS:
        pos += 1
    return pos


def read_int(data, pos):
    pos = skip_ws(data, pos)
    start = pos
    while pos < len(data) and 48 <= data[pos] <= 57:
        pos += 1
    if pos == start:
        raise ValueError("expected integer")
    return int(data[start:pos]), pos


def read_name(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 1] != b"/":
        raise ValueError("expected name")
    pos += 1
    start = pos
    while pos < len(data) and data[pos] not in WS and data[pos] not in b"[]<>()/{}":
        pos += 1
    return data[start - 1:pos], pos


def parse_value(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise ValueError("unexpected end")
    c = data[pos:pos + 1]
    if c == b"/":
        return read_name(data, pos)
    if c == b"[":
        pos += 1
        arr = []
        while True:
            pos = skip_ws(data, pos)
            if data[pos:pos + 1] == b"]":
                return arr, pos + 1
            v, pos = parse_value(data, pos)
            arr.append(v)
    if c == b"<":
        return parse_dict(data, pos)
    if c == b"(":
        depth = 0
        start = pos
        while pos < len(data):
            ch = data[pos:pos + 1]
            if ch == b"\\":
                pos += 2
                continue
            if ch == b"(":
                depth += 1
            elif ch == b")":
                depth -= 1
                if depth == 0:
                    return data[start:pos + 1], pos + 1
            pos += 1
        raise ValueError("unterminated string")
    m = re.match(rb"(\d+)\s+(\d+)\s+R", data[pos:pos + 64])
    if m:
        pos += m.end()
        return (int(m.group(1)), int(m.group(2))), pos
    m = re.match(rb"(\d+)", data[pos:pos + 64])
    if m:
        pos += m.end()
        return int(m.group(1)), pos
    raise ValueError("unexpected token")


def parse_dict(data, pos):
    if data[pos:pos + 2] != b"<<":
        raise ValueError("expected <<")
    pos += 2
    result = {}
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 2] == b">>":
            return result, pos + 2
        name, pos = read_name(data, pos)
        val, pos = parse_value(data, pos)
        result[name] = val


def read_object(data, offset):
    """Return (num, gen, body_bytes, is_stream). body excludes 'obj'/'endobj'."""
    pos = offset
    num, pos = read_int(data, pos)
    gen, pos = read_int(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise ValueError(f"bad object header at {offset}")
    pos = skip_ws(data, pos + 3)
    body_start = pos
    if data[pos:pos + 2] == b"<<":
        _, pos = parse_dict(data, pos)
        pos = skip_ws(data, pos)
        if data[pos:pos + 6] == b"stream":
            sd = pos + 6
            if data[sd:sd + 2] == b"\r\n":
                sd += 2
            elif data[sd:sd + 1] in (b"\n", b"\r"):
                sd += 1
            end = data.find(b"endstream", sd)
            if end < 0:
                raise ValueError("no endstream")
            body_end = end + len(b"endstream")
            pos2 = skip_ws(data, body_end)
            if data[pos2:pos2 + 6] != b"endobj":
                raise ValueError("no endobj after stream")
            return num, gen, data[body_start:body_end].rstrip(b"\r\n"), True
    end = data.find(b"endobj", pos)
    if end < 0:
        raise ValueError("no endobj")
    return num, gen, data[body_start:end].rstrip(b"\r\n"), False


def find_startxref(data):
    pos = data.rfind(b"startxref")
    if pos < 0:
        raise ValueError("no startxref")
    m = re.search(rb"startxref\s+(\d+)", data[pos:])
    if not m:
        raise ValueError("bad startxref")
    return int(m.group(1))


def parse_classic_xref(data, offset):
    entries = {}
    pos = offset
    if data[pos:pos + 4] != b"xref":
        raise ValueError("not a classic xref")
    pos += 4
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 7] == b"trailer":
            break
        try:
            start, pos = read_int(data, pos)
            count, pos = read_int(data, pos)
        except ValueError:
            break
        for i in range(count):
            pos = skip_ws(data, pos)
            line_end = data.find(b"\n", pos)
            line = data[pos:line_end] if line_end >= 0 else data[pos:pos + 24]
            parts = line.split()
            if len(parts) < 3:
                raise ValueError("bad xref entry")
            off = int(parts[0])
            gen = int(parts[1])
            typ = parts[2]
            if typ == b"n":
                entries[start + i] = (off, gen, b"n")
            else:
                entries[start + i] = (0, gen, b"f")
            pos = line_end + 1 if line_end >= 0 else pos + 24
    return entries, pos


def parse_trailer(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise ValueError("no trailer")
    pos = skip_ws(data, pos + 7)
    return parse_dict(data, pos)


def parse_xref_stream(data, offset):
    num, gen, body, is_stream = read_object(data, offset)
    if not is_stream:
        raise ValueError("expected xref stream")
    d, _ = parse_dict(body, 0)
    W = d.get(b"/W")
    size = d.get(b"/Size")
    if not isinstance(W, list) or len(W) != 3:
        raise ValueError("bad /W in xref stream")
    index = d.get(b"/Index") or [0, size]
    si = body.find(b"stream")
    sd = si + 6
    if body[sd:sd + 2] == b"\r\n":
        sd += 2
    elif body[sd:sd + 1] in (b"\n", b"\r"):
        sd += 1
    end = body.find(b"endstream", sd)
    raw = body[sd:end] if end >= 0 else body[sd:]
    sdata = zlib.decompress(raw)
    w1, w2, w3 = W
    rlen = w1 + w2 + w3
    entries = {}
    base = 0
    for i in range(0, len(index), 2):
        start, count = index[i], index[i + 1]
        for j in range(count):
            rec = sdata[base + j * rlen: base + (j + 1) * rlen]

            def fld(o, w):
                return int.from_bytes(rec[o:o + w], "big") if w > 0 else 0

            typ = fld(0, w1)
            f2 = fld(w1, w2)
            f3 = fld(w1 + w2, w3)
            if typ == 1:
                entries[start + j] = (f2, f3, b"n")
            elif typ == 2:
                entries[start + j] = (None, (f2, f3), b"c")
            else:
                entries[start + j] = (0, 0, b"f")
        base += count * rlen
    return entries, d


def parse_pdf(data):
    xref_off = find_startxref(data)
    entries = {}
    trailer = {}
    off = xref_off
    while off is not None:
        if data[off:off + 4] == b"xref":
            e, pos = parse_classic_xref(data, off)
            tr = parse_trailer(data, pos)
        else:
            e, tr = parse_xref_stream(data, off)
        for k, v in e.items():
            if k not in entries:
                entries[k] = v
        if not trailer:
            trailer = tr
        prev = tr.get(b"/Prev")
        off = int(prev) if prev else None
    root_ref = trailer.get(b"/Root")
    if not isinstance(root_ref, tuple):
        raise ValueError("no /Root in trailer")
    root_num = root_ref[0]
    re_ = entries.get(root_num)
    if not re_ or re_[2] != b"n":
        raise ValueError("catalog object not readable")
    rn, rg, rbody, ris = read_object(data, re_[0])
    cat, _ = parse_dict(rbody, 0)
    pages_ref = cat.get(b"/Pages")
    if not isinstance(pages_ref, tuple):
        raise ValueError("no /Pages in catalog")
    pages_num = pages_ref[0]
    return {
        "entries": entries,
        "trailer": trailer,
        "root_num": root_num,
        "pages_num": pages_num,
    }


def count_pages(data, entries, pages_num):
    seen = set()

    def walk(num):
        if num in seen:
            return 0
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return 0
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return 1
        kids = d.get(b"/Kids")
        if not isinstance(kids, list):
            return 0
        total = 0
        for kid in kids:
            if isinstance(kid, tuple):
                total += walk(kid[0])
        return total

    return walk(pages_num)


def first_page_num(data, entries, pages_num):
    seen = set()
    num = pages_num
    while True:
        if num in seen:
            return None
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return None
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return num
        kids = d.get(b"/Kids")
        if not isinstance(kids, list) or not kids:
            return None
        first = kids[0]
        if not isinstance(first, tuple):
            return None
        num = first[0]


def extract_page_text(data, entries, page_num):
    e = entries.get(page_num)
    if not e or e[2] != b"n":
        return ""
    n, g, body, is_stream = read_object(data, e[0])
    d, _ = parse_dict(body, 0)
    contents = d.get(b"/Contents")
    refs = []
    if isinstance(contents, tuple):
        refs.append(contents)
    elif isinstance(contents, list):
        refs = [c for c in contents if isinstance(c, tuple)]
    parts = []
    for ref in refs:
        ce = entries.get(ref[0])
        if not ce or ce[2] != b"n":
            continue
        cn, cg, cbody, cis = read_object(data, ce[0])
        si = cbody.find(b"stream")
        if si < 0:
            continue
        sd = si + 6
        if cbody[sd:sd + 2] == b"\r\n":
            sd += 2
        elif cbody[sd:sd + 1] in (b"\n", b"\r"):
            sd += 1
        end = cbody.find(b"endstream", sd)
        raw = cbody[sd:end] if end >= 0 else cbody[sd:]
        if raw[:2] == b"\x78\x9c":
            try:
                raw = zlib.decompress(raw)
            except Exception:
                pass
        parts.append(raw.decode("latin-1", "replace"))
    return "\n".join(parts)


# --------------------------------------------------------------------------
# Library / tool detection
# --------------------------------------------------------------------------
def import_pdf_libs():
    libs = {}
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    for pat in (".codex/skills/pdf/**/site-packages",
                ".codex/skills/pdf/**/dist-packages"):
        for sp in sorted(glob.glob(pat, recursive=True)):
            if sp not in sys.path:
                sys.path.insert(0, sp)
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    try:
        import fitz
        libs["fitz"] = fitz
        return libs
    except Exception:
        pass
    try:
        import pypdfium2 as pdfium
        libs["pdfium"] = pdfium
        return libs
    except Exception:
        pass
    return libs


# --------------------------------------------------------------------------
# Merge strategies
# --------------------------------------------------------------------------
def merge_with_pypdf(cover_bytes, PdfReader, PdfWriter):
    reader = PdfReader(io.BytesIO(cover_bytes))
    writer = PdfWriter()
    writer.add_page(reader.pages[0])
    rep = PdfReader(REPORT)
    for p in rep.pages:
        writer.add_page(p)
    with open(REPORT, "wb") as fh:
        writer.write(fh)
    log("merged via pypdf")


def merge_with_fitz(cover_bytes, fitz):
    cover = fitz.open(stream=cover_bytes, filetype="pdf")
    doc = fitz.open(REPORT)
    doc.insert_pdf(cover, start_at=0)
    data = doc.tobytes(garbage=3, deflate=True)
    doc.close()
    cover.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via PyMuPDF")


def merge_with_pdfium(cover_bytes, pdfium):
    cover = pdfium.PdfDocument.new(cover_bytes)
    doc = pdfium.PdfDocument(REPORT)
    cover.import_pages(doc, pages=list(range(len(doc))), index=1)
    data = cover.tobytes()
    cover.close()
    doc.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via pypdfium2")


def merge_with_cli(cover_bytes, tool_name, argv_builder):
    tmpdir = tempfile.mkdtemp(prefix="cover_task_")
    try:
        cover_path = os.path.join(tmpdir, "cover.pdf")
        out_path = os.path.join(tmpdir, "out.pdf")
        with open(cover_path, "wb") as fh:
            fh.write(cover_bytes)
        cmd = argv_builder(cover_path, out_path)
        proc = subprocess.run(cmd, capture_output=True, text=True)
        if proc.returncode != 0:
            raise RuntimeError(f"{tool_name} failed: {proc.stderr or proc.stdout}")
        if not os.path.exists(out_path):
            raise RuntimeError(f"{tool_name} produced no output")
        os.replace(out_path, REPORT)
        log(f"merged via {tool_name}")
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


def merge_pure_python(data, cover_bytes):
    info = parse_pdf(data)
    entries = info["entries"]
    trailer = info["trailer"]
    root_num = info["root_num"]
    pages_num = info["pages_num"]
    if b"/Encrypt" in trailer:
        raise RuntimeError("encrypted PDF cannot be merged with pure-Python merger")
    pe = entries.get(pages_num)
    if not pe or pe[2] != b"n":
        raise RuntimeError("pages object is compressed; pure-Python merger unsupported")
    pn, pg, pbody, pis = read_object(data, pe[0])
    if pis:
        raise RuntimeError("pages object is a stream; pure-Python merger unsupported")
    pd, _ = parse_dict(pbody, 0)
    kids = pd.get(b"/Kids") or []
    count = pd.get(b"/Count")
    if count is None:
        count = len([k for k in kids if isinstance(k, tuple)])
    m = re.search(rb"/Kids\s*\[(.*?)\]", pbody, re.S)
    kids_raw = m.group(1).strip() if m else b""
    max_num = max(entries) if entries else 0
    my_page = max_num + 1
    my_contents = max_num + 2
    my_font1 = max_num + 3
    my_font2 = max_num + 4
    new_size = my_font2 + 1

    content, today = make_cover_content()
    my_page_body = (b"<< /Type /Page /Parent %d 0 R /MediaBox [0 0 612 792] "
                    b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                    b"/Contents %d 0 R >>") % (pages_num, my_font1, my_font2, my_contents)
    my_contents_body = (b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
                        + content + b"\nendstream")
    my_font1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"
    my_font2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"

    new_kids = b"%d 0 R " % my_page
    if kids_raw:
        new_kids += kids_raw
    new_pbody = re.sub(rb"/Kids\s*\[.*?\]", b"/Kids [" + new_kids + b"]",
                       pbody, count=1, flags=re.S)
    new_pbody = re.sub(rb"/Count\s+\d+", b"/Count %d" % (count + 1),
                       new_pbody, count=1)

    out = bytearray(b"%PDF-1.4\n")
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"

    emit(my_page, my_page_body)
    emit(my_contents, my_contents_body)
    emit(my_font1, my_font1_body)
    emit(my_font2, my_font2_body)
    emit(pages_num, new_pbody)
    for num in sorted(entries):
        if num in (my_page, my_contents, my_font1, my_font2) or num == pages_num:
            continue
        off_, gen, typ = entries[num]
        if typ != b"n" or off_ is None:
            continue
        n2, g2, body2, is_stream2 = read_object(data, off_)
        emit(num, body2)

    xref_pos = len(out)
    out += b"xref\n0 %d\n" % new_size
    out += b"0000000000 65535 f \n"
    for num in range(1, new_size):
        if num in offsets:
            out += b"%010d 00000 n \n" % offsets[num]
        else:
            out += b"%010d 65535 f \n" % 0
    trailer_out = b"<< /Size %d /Root %d 0 R" % (new_size, root_num)
    info_ref = trailer.get(b"/Info")
    if isinstance(info_ref, tuple):
        trailer_out += b" /Info %d %d R" % info_ref
    trailer_out += b" >>"
    out += b"trailer\n" + trailer_out + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    with open(REPORT, "wb") as fh:
        fh.write(bytes(out))
    log("merged via pure-Python PDF merger")


# --------------------------------------------------------------------------
# Main
# --------------------------------------------------------------------------
def main():
    if not os.path.exists(REPORT):
        log(f"error: {REPORT} not found in {os.getcwd()}")
        return 1

    cover_bytes, today = build_cover_pdf_bytes()
    try:
        parse_pdf(cover_bytes)
    except Exception as exc:
        log(f"error: generated cover page failed self-check: {exc}")
        return 1
    log(f"cover page built for date '{today}'")

    original = open(REPORT, "rb").read()
    old_count = None
    try:
        info0 = parse_pdf(original)
        old_count = count_pages(original, info0["entries"], info0["pages_num"])
        log(f"report.pdf: {old_count} page(s) before change")
    except Exception as exc:
        log(f"note: stdlib pre-parse unavailable ({exc})")

    libs = import_pdf_libs()
    merged = False
    if "pypdf" in libs:
        try:
            merge_with_pypdf(cover_bytes, libs["pypdf"][0], libs["pypdf"][1])
            merged = True
        except Exception as exc:
            log(f"pypdf merge failed: {exc}")
    if not merged and "fitz" in libs:
        try:
            merge_with_fitz(cover_bytes, libs["fitz"])
            merged = True
        except Exception as exc:
            log(f"PyMuPDF merge failed: {exc}")
    if not merged and "pdfium" in libs:
        try:
            merge_with_pdfium(cover_bytes, libs["pdfium"])
            merged = True
        except Exception as exc:
            log(f"pypdfium2 merge failed: {exc}")
    if not merged and shutil.which("qpdf"):
        try:
            merge_with_cli(cover_bytes, "qpdf",
                           lambda c, o: ["qpdf", "--empty", "--pages", c, REPORT, "--", o])
            merged = True
        except Exception as exc:
            log(f"qpdf merge failed: {exc}")
    if not merged and shutil.which("pdftk"):
        try:
            merge_with_cli(cover_bytes, "pdftk",
                           lambda c, o: ["pdftk", c, REPORT, "cat", "output", o])
            merged = True
        except Exception as exc:
            log(f"pdftk merge failed: {exc}")
    if not merged and shutil.which("gs"):
        try:
            merge_with_cli(cover_bytes, "gs",
                           lambda c, o: ["gs", "-q", "-dNOPAUSE", "-dBATCH",
                                         "-sDEVICE=pdfwrite",
                                         "-sOutputFile=" + o, c, REPORT])
            merged = True
        except Exception as exc:
            log(f"gs merge failed: {exc}")
    if not merged:
        try:
            merge_pure_python(original, cover_bytes)
            merged = True
        except Exception as exc:
            log(f"pure-Python merge failed: {exc}")

    if not merged:
        log("error: no merge strategy succeeded")
        return 1

    # ---------------- validation ----------------
    data = open(REPORT, "rb").read()
    ok = False
    if "pypdf" in libs:
        try:
            PdfReader = libs["pypdf"][0]
            reader = PdfReader(REPORT)
            total = len(reader.pages)
            t = reader.pages[0].extract_text() or ""
            ok_title = TITLE in t
            ok_date = today in t
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (pypdf): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            log(f"pypdf validation failed: {exc}")
    if not ok:
        try:
            info = parse_pdf(data)
            total = count_pages(data, info["entries"], info["pages_num"])
            fp = first_page_num(data, info["entries"], info["pages_num"])
            text = extract_page_text(data, info["entries"], fp) if fp else ""
            ok_title = TITLE in text
            ok_date = today in text
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (stdlib): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            log(f"stdlib validation failed: {exc}")

    if not ok:
        log("error: cover page validation failed")
        return 1
    log("OK: cover page prepended to report.pdf")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Prepend a cover page to report.pdf with the exact title 'Annual Financial
Report' and the current (operator runtime) date. Only report.pdf is modified.

Strategy: the cover page is generated as a minimal valid PDF using only the
Python standard library. The merge is attempted with any available PDF library
(pypdf/PyPDF2, PyMuPDF, pypdfium2), then with CLI tools (qpdf, pdftk, gs), and
finally with a pure-Python PDF merger. The result is validated by re-parsing.
"""
import datetime
import glob
import io
import os
import re
import shutil
import subprocess
import sys
import tempfile
import traceback
import zlib

REPORT = "report.pdf"
TITLE = "Annual Financial Report"
WS = b" \t\r\n\0"


def log(msg):
    print(msg, flush=True)


def today_str():
    return datetime.date.today().strftime("%B %d, %Y")


# --------------------------------------------------------------------------
# Minimal PDF generation (standard library only)
# --------------------------------------------------------------------------
def pdf_escape(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def make_cover_content():
    today = today_str()
    W, H = 612.0, 792.0

    def w_est(s, size, factor):
        return len(s) * size * factor

    content = (
        "BT\n"
        "/F1 30 Tf\n"
        f"{((W - w_est(TITLE, 30, 0.55)) / 2.0):.2f} {H / 2.0 + 30:.2f} Td\n"
        f"({pdf_escape(TITLE)}) Tj\n"
        "/F2 16 Tf\n"
        "0 -60 Td\n"
        f"({pdf_escape(today)}) Tj\n"
        "ET\n"
    ).encode("latin-1")
    return content, today


def build_cover_pdf_bytes():
    """Return (bytes, today) of a one-page cover PDF (objects 1..6)."""
    content, today = make_cover_content()
    objects = [
        (1, b"<< /Type /Catalog /Pages 2 0 R >>"),
        (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>"),
        (3, (b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
             b"/Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> "
             b"/Contents 4 0 R >>")),
        (4, b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
            + content + b"\nendstream"),
        (5, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"),
        (6, b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"),
    ]
    out = bytearray(b"%PDF-1.4\n")
    offsets = {}
    for num, body in objects:
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"
    xref_pos = len(out)
    out += b"xref\n0 7\n"
    out += b"0000000000 65535 f \n"
    for num in range(1, 7):
        out += b"%010d 00000 n \n" % offsets[num]
    out += b"trailer\n<< /Size 7 /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    return bytes(out), today


# --------------------------------------------------------------------------
# Minimal PDF object parser (standard library only)
# --------------------------------------------------------------------------
def skip_ws(data, pos):
    n = len(data)
    while pos < n and data[pos] in WS:
        pos += 1
    return pos


def read_int(data, pos):
    pos = skip_ws(data, pos)
    start = pos
    while pos < len(data) and 48 <= data[pos] <= 57:
        pos += 1
    if pos == start:
        raise ValueError("expected integer")
    return int(data[start:pos]), pos


def read_name(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 1] != b"/":
        raise ValueError("expected name")
    pos += 1
    start = pos
    while pos < len(data) and data[pos] not in WS and data[pos] not in b"[]<>()/{}":
        pos += 1
    return data[start - 1:pos], pos


def parse_value(data, pos):
    pos = skip_ws(data, pos)
    if pos >= len(data):
        raise ValueError("unexpected end")
    c = data[pos:pos + 1]
    if c == b"/":
        return read_name(data, pos)
    if c == b"[":
        pos += 1
        arr = []
        while True:
            pos = skip_ws(data, pos)
            if data[pos:pos + 1] == b"]":
                return arr, pos + 1
            v, pos = parse_value(data, pos)
            arr.append(v)
    if c == b"<":
        return parse_dict(data, pos)
    if c == b"(":
        depth = 0
        start = pos
        while pos < len(data):
            ch = data[pos:pos + 1]
            if ch == b"\\":
                pos += 2
                continue
            if ch == b"(":
                depth += 1
            elif ch == b")":
                depth -= 1
                if depth == 0:
                    return data[start:pos + 1], pos + 1
            pos += 1
        raise ValueError("unterminated string")
    m = re.match(rb"(\d+)\s+(\d+)\s+R", data[pos:pos + 64])
    if m:
        pos += m.end()
        return (int(m.group(1)), int(m.group(2))), pos
    m = re.match(rb"(\d+)", data[pos:pos + 64])
    if m:
        pos += m.end()
        return int(m.group(1)), pos
    raise ValueError("unexpected token")


def parse_dict(data, pos):
    if data[pos:pos + 2] != b"<<":
        raise ValueError("expected <<")
    pos += 2
    result = {}
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 2] == b">>":
            return result, pos + 2
        name, pos = read_name(data, pos)
        val, pos = parse_value(data, pos)
        result[name] = val


def read_object(data, offset):
    """Return (num, gen, body_bytes, is_stream). body excludes 'obj'/'endobj'."""
    pos = offset
    num, pos = read_int(data, pos)
    gen, pos = read_int(data, pos)
    pos = skip_ws(data, pos)
    if data[pos:pos + 3] != b"obj":
        raise ValueError(f"bad object header at {offset}")
    pos = skip_ws(data, pos + 3)
    body_start = pos
    if data[pos:pos + 2] == b"<<":
        _, pos = parse_dict(data, pos)
        pos = skip_ws(data, pos)
        if data[pos:pos + 6] == b"stream":
            sd = pos + 6
            if data[sd:sd + 2] == b"\r\n":
                sd += 2
            elif data[sd:sd + 1] in (b"\n", b"\r"):
                sd += 1
            end = data.find(b"endstream", sd)
            if end < 0:
                raise ValueError("no endstream")
            body_end = end + len(b"endstream")
            pos2 = skip_ws(data, body_end)
            if data[pos2:pos2 + 6] != b"endobj":
                raise ValueError("no endobj after stream")
            return num, gen, data[body_start:body_end].rstrip(b"\r\n"), True
    end = data.find(b"endobj", pos)
    if end < 0:
        raise ValueError("no endobj")
    return num, gen, data[body_start:end].rstrip(b"\r\n"), False


def find_startxref(data):
    pos = data.rfind(b"startxref")
    if pos < 0:
        raise ValueError("no startxref")
    m = re.search(rb"startxref\s+(\d+)", data[pos:])
    if not m:
        raise ValueError("bad startxref")
    return int(m.group(1))


def parse_classic_xref(data, offset):
    entries = {}
    pos = offset
    if data[pos:pos + 4] != b"xref":
        raise ValueError("not a classic xref")
    pos += 4
    while True:
        pos = skip_ws(data, pos)
        if data[pos:pos + 7] == b"trailer":
            break
        try:
            start, pos = read_int(data, pos)
            count, pos = read_int(data, pos)
        except ValueError:
            break
        for i in range(count):
            pos = skip_ws(data, pos)
            line_end = data.find(b"\n", pos)
            line = data[pos:line_end] if line_end >= 0 else data[pos:pos + 24]
            parts = line.split()
            if len(parts) < 3:
                raise ValueError("bad xref entry")
            off = int(parts[0])
            gen = int(parts[1])
            typ = parts[2]
            if typ == b"n":
                entries[start + i] = (off, gen, b"n")
            else:
                entries[start + i] = (0, gen, b"f")
            pos = line_end + 1 if line_end >= 0 else pos + 24
    return entries, pos


def parse_trailer(data, pos):
    pos = skip_ws(data, pos)
    if data[pos:pos + 7] != b"trailer":
        raise ValueError("no trailer")
    pos = skip_ws(data, pos + 7)
    return parse_dict(data, pos)


def parse_xref_stream(data, offset):
    num, gen, body, is_stream = read_object(data, offset)
    if not is_stream:
        raise ValueError("expected xref stream")
    d, _ = parse_dict(body, 0)
    W = d.get(b"/W")
    size = d.get(b"/Size")
    if not isinstance(W, list) or len(W) != 3:
        raise ValueError("bad /W in xref stream")
    index = d.get(b"/Index") or [0, size]
    si = body.find(b"stream")
    sd = si + 6
    if body[sd:sd + 2] == b"\r\n":
        sd += 2
    elif body[sd:sd + 1] in (b"\n", b"\r"):
        sd += 1
    end = body.find(b"endstream", sd)
    raw = body[sd:end] if end >= 0 else body[sd:]
    sdata = zlib.decompress(raw)
    w1, w2, w3 = W
    rlen = w1 + w2 + w3
    entries = {}
    base = 0
    for i in range(0, len(index), 2):
        start, count = index[i], index[i + 1]
        for j in range(count):
            rec = sdata[base + j * rlen: base + (j + 1) * rlen]

            def fld(o, w):
                return int.from_bytes(rec[o:o + w], "big") if w > 0 else 0

            typ = fld(0, w1)
            f2 = fld(w1, w2)
            f3 = fld(w1 + w2, w3)
            if typ == 1:
                entries[start + j] = (f2, f3, b"n")
            elif typ == 2:
                entries[start + j] = (None, (f2, f3), b"c")
            else:
                entries[start + j] = (0, 0, b"f")
        base += count * rlen
    return entries, d


def parse_pdf(data):
    xref_off = find_startxref(data)
    entries = {}
    trailer = {}
    off = xref_off
    while off is not None:
        if data[off:off + 4] == b"xref":
            e, pos = parse_classic_xref(data, off)
            tr = parse_trailer(data, pos)
        else:
            e, tr = parse_xref_stream(data, off)
        for k, v in e.items():
            if k not in entries:
                entries[k] = v
        if not trailer:
            trailer = tr
        prev = tr.get(b"/Prev")
        off = int(prev) if prev else None
    root_ref = trailer.get(b"/Root")
    if not isinstance(root_ref, tuple):
        raise ValueError("no /Root in trailer")
    root_num = root_ref[0]
    re_ = entries.get(root_num)
    if not re_ or re_[2] != b"n":
        raise ValueError("catalog object not readable")
    rn, rg, rbody, ris = read_object(data, re_[0])
    cat, _ = parse_dict(rbody, 0)
    pages_ref = cat.get(b"/Pages")
    if not isinstance(pages_ref, tuple):
        raise ValueError("no /Pages in catalog")
    pages_num = pages_ref[0]
    return {
        "entries": entries,
        "trailer": trailer,
        "root_num": root_num,
        "pages_num": pages_num,
    }


def count_pages(data, entries, pages_num):
    seen = set()

    def walk(num):
        if num in seen:
            return 0
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return 0
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return 1
        kids = d.get(b"/Kids")
        if not isinstance(kids, list):
            return 0
        total = 0
        for kid in kids:
            if isinstance(kid, tuple):
                total += walk(kid[0])
        return total

    return walk(pages_num)


def first_page_num(data, entries, pages_num):
    seen = set()
    num = pages_num
    while True:
        if num in seen:
            return None
        seen.add(num)
        e = entries.get(num)
        if not e or e[2] != b"n":
            return None
        n, g, body, is_stream = read_object(data, e[0])
        d, _ = parse_dict(body, 0)
        if d.get(b"/Type") == b"/Page":
            return num
        kids = d.get(b"/Kids")
        if not isinstance(kids, list) or not kids:
            return None
        first = kids[0]
        if not isinstance(first, tuple):
            return None
        num = first[0]


def extract_page_text(data, entries, page_num):
    e = entries.get(page_num)
    if not e or e[2] != b"n":
        return ""
    n, g, body, is_stream = read_object(data, e[0])
    d, _ = parse_dict(body, 0)
    contents = d.get(b"/Contents")
    refs = []
    if isinstance(contents, tuple):
        refs.append(contents)
    elif isinstance(contents, list):
        refs = [c for c in contents if isinstance(c, tuple)]
    parts = []
    for ref in refs:
        ce = entries.get(ref[0])
        if not ce or ce[2] != b"n":
            continue
        cn, cg, cbody, cis = read_object(data, ce[0])
        si = cbody.find(b"stream")
        if si < 0:
            continue
        sd = si + 6
        if cbody[sd:sd + 2] == b"\r\n":
            sd += 2
        elif cbody[sd:sd + 1] in (b"\n", b"\r"):
            sd += 1
        end = cbody.find(b"endstream", sd)
        raw = cbody[sd:end] if end >= 0 else cbody[sd:]
        if raw[:2] == b"\x78\x9c":
            try:
                raw = zlib.decompress(raw)
            except Exception:
                pass
        parts.append(raw.decode("latin-1", "replace"))
    return "\n".join(parts)


# --------------------------------------------------------------------------
# Library / tool detection
# --------------------------------------------------------------------------
def import_pdf_libs():
    libs = {}
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    for pat in (".codex/skills/pdf/**/site-packages",
                ".codex/skills/pdf/**/dist-packages"):
        for sp in sorted(glob.glob(pat, recursive=True)):
            if sp not in sys.path:
                sys.path.insert(0, sp)
    try:
        from pypdf import PdfReader, PdfWriter
        libs["pypdf"] = (PdfReader, PdfWriter)
        return libs
    except Exception:
        pass
    try:
        import fitz
        libs["fitz"] = fitz
        return libs
    except Exception:
        pass
    try:
        import pypdfium2 as pdfium
        libs["pdfium"] = pdfium
        return libs
    except Exception:
        pass
    return libs


# --------------------------------------------------------------------------
# Merge strategies
# --------------------------------------------------------------------------
def merge_with_pypdf(cover_bytes, PdfReader, PdfWriter):
    reader = PdfReader(io.BytesIO(cover_bytes))
    writer = PdfWriter()
    writer.add_page(reader.pages[0])
    rep = PdfReader(REPORT)
    for p in rep.pages:
        writer.add_page(p)
    with open(REPORT, "wb") as fh:
        writer.write(fh)
    log("merged via pypdf")


def merge_with_fitz(cover_bytes, fitz):
    cover = fitz.open(stream=cover_bytes, filetype="pdf")
    doc = fitz.open(REPORT)
    doc.insert_pdf(cover, start_at=0)
    data = doc.tobytes(garbage=3, deflate=True)
    doc.close()
    cover.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via PyMuPDF")


def merge_with_pdfium(cover_bytes, pdfium):
    cover = pdfium.PdfDocument.new(cover_bytes)
    doc = pdfium.PdfDocument(REPORT)
    cover.import_pages(doc, pages=list(range(len(doc))), index=1)
    data = cover.tobytes()
    cover.close()
    doc.close()
    with open(REPORT, "wb") as fh:
        fh.write(data)
    log("merged via pypdfium2")


def merge_with_cli(cover_bytes, tool_name, argv_builder):
    tmpdir = tempfile.mkdtemp(prefix="cover_task_")
    try:
        cover_path = os.path.join(tmpdir, "cover.pdf")
        out_path = os.path.join(tmpdir, "out.pdf")
        with open(cover_path, "wb") as fh:
            fh.write(cover_bytes)
        cmd = argv_builder(cover_path, out_path)
        proc = subprocess.run(cmd, capture_output=True, text=True)
        if proc.returncode != 0:
            raise RuntimeError(f"{tool_name} failed: {proc.stderr or proc.stdout}")
        if not os.path.exists(out_path):
            raise RuntimeError(f"{tool_name} produced no output")
        os.replace(out_path, REPORT)
        log(f"merged via {tool_name}")
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


def merge_pure_python(data, cover_bytes):
    info = parse_pdf(data)
    entries = info["entries"]
    trailer = info["trailer"]
    root_num = info["root_num"]
    pages_num = info["pages_num"]
    if b"/Encrypt" in trailer:
        raise RuntimeError("encrypted PDF cannot be merged with pure-Python merger")
    pe = entries.get(pages_num)
    if not pe or pe[2] != b"n":
        raise RuntimeError("pages object is compressed; pure-Python merger unsupported")
    pn, pg, pbody, pis = read_object(data, pe[0])
    if pis:
        raise RuntimeError("pages object is a stream; pure-Python merger unsupported")
    pd, _ = parse_dict(pbody, 0)
    kids = pd.get(b"/Kids") or []
    count = pd.get(b"/Count")
    if count is None:
        count = len([k for k in kids if isinstance(k, tuple)])
    m = re.search(rb"/Kids\s*\[(.*?)\]", pbody, re.S)
    kids_raw = m.group(1).strip() if m else b""
    max_num = max(entries) if entries else 0
    my_page = max_num + 1
    my_contents = max_num + 2
    my_font1 = max_num + 3
    my_font2 = max_num + 4
    new_size = my_font2 + 1

    content, today = make_cover_content()
    my_page_body = (b"<< /Type /Page /Parent %d 0 R /MediaBox [0 0 612 792] "
                    b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> "
                    b"/Contents %d 0 R >>") % (pages_num, my_font1, my_font2, my_contents)
    my_contents_body = (b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
                        + content + b"\nendstream")
    my_font1_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Bold >>"
    my_font2_body = b"<< /Type /Font /Subtype /Type1 /BaseFont /Times-Roman >>"

    new_kids = b"%d 0 R " % my_page
    if kids_raw:
        new_kids += kids_raw
    new_pbody = re.sub(rb"/Kids\s*\[.*?\]", b"/Kids [" + new_kids + b"]",
                       pbody, count=1, flags=re.S)
    new_pbody = re.sub(rb"/Count\s+\d+", b"/Count %d" % (count + 1),
                       new_pbody, count=1)

    out = bytearray(b"%PDF-1.4\n")
    offsets = {}

    def emit(num, body):
        offsets[num] = len(out)
        out += b"%d 0 obj\n" % num
        out += body
        out += b"\nendobj\n"

    emit(my_page, my_page_body)
    emit(my_contents, my_contents_body)
    emit(my_font1, my_font1_body)
    emit(my_font2, my_font2_body)
    emit(pages_num, new_pbody)
    for num in sorted(entries):
        if num in (my_page, my_contents, my_font1, my_font2) or num == pages_num:
            continue
        off_, gen, typ = entries[num]
        if typ != b"n" or off_ is None:
            continue
        n2, g2, body2, is_stream2 = read_object(data, off_)
        emit(num, body2)

    xref_pos = len(out)
    out += b"xref\n0 %d\n" % new_size
    out += b"0000000000 65535 f \n"
    for num in range(1, new_size):
        if num in offsets:
            out += b"%010d 00000 n \n" % offsets[num]
        else:
            out += b"%010d 65535 f \n" % 0
    trailer_out = b"<< /Size %d /Root %d 0 R" % (new_size, root_num)
    info_ref = trailer.get(b"/Info")
    if isinstance(info_ref, tuple):
        trailer_out += b" /Info %d %d R" % info_ref
    trailer_out += b" >>"
    out += b"trailer\n" + trailer_out + b"\nstartxref\n%d\n%%%%EOF\n" % xref_pos
    with open(REPORT, "wb") as fh:
        fh.write(bytes(out))
    log("merged via pure-Python PDF merger")


# --------------------------------------------------------------------------
# Main
# --------------------------------------------------------------------------
def main():
    if not os.path.exists(REPORT):
        log(f"error: {REPORT} not found in {os.getcwd()}")
        return 1

    cover_bytes, today = build_cover_pdf_bytes()
    try:
        parse_pdf(cover_bytes)
    except Exception as exc:
        traceback.print_exc()
        log(f"error: generated cover page failed self-check: {exc}")
        return 1
    log(f"cover page built for date '{today}'")

    original = open(REPORT, "rb").read()
    old_count = None
    try:
        info0 = parse_pdf(original)
        old_count = count_pages(original, info0["entries"], info0["pages_num"])
        log(f"report.pdf: {old_count} page(s) before change")
    except Exception as exc:
        log(f"note: stdlib pre-parse unavailable ({exc})")

    libs = import_pdf_libs()
    merged = False
    if "pypdf" in libs:
        try:
            merge_with_pypdf(cover_bytes, libs["pypdf"][0], libs["pypdf"][1])
            merged = True
        except Exception as exc:
            log(f"pypdf merge failed: {exc}")
    if not merged and "fitz" in libs:
        try:
            merge_with_fitz(cover_bytes, libs["fitz"])
            merged = True
        except Exception as exc:
            log(f"PyMuPDF merge failed: {exc}")
    if not merged and "pdfium" in libs:
        try:
            merge_with_pdfium(cover_bytes, libs["pdfium"])
            merged = True
        except Exception as exc:
            log(f"pypdfium2 merge failed: {exc}")
    if not merged and shutil.which("qpdf"):
        try:
            merge_with_cli(cover_bytes, "qpdf",
                           lambda c, o: ["qpdf", "--empty", "--pages", c, REPORT, "--", o])
            merged = True
        except Exception as exc:
            log(f"qpdf merge failed: {exc}")
    if not merged and shutil.which("pdftk"):
        try:
            merge_with_cli(cover_bytes, "pdftk",
                           lambda c, o: ["pdftk", c, REPORT, "cat", "output", o])
            merged = True
        except Exception as exc:
            log(f"pdftk merge failed: {exc}")
    if not merged and shutil.which("gs"):
        try:
            merge_with_cli(cover_bytes, "gs",
                           lambda c, o: ["gs", "-q", "-dNOPAUSE", "-dBATCH",
                                         "-sDEVICE=pdfwrite",
                                         "-sOutputFile=" + o, c, REPORT])
            merged = True
        except Exception as exc:
            log(f"gs merge failed: {exc}")
    if not merged:
        try:
            merge_pure_python(original, cover_bytes)
            merged = True
        except Exception as exc:
            log(f"pure-Python merge failed: {exc}")

    if not merged:
        log("error: no merge strategy succeeded")
        return 1

    # ---------------- validation ----------------
    data = open(REPORT, "rb").read()
    ok = False
    if "pypdf" in libs:
        try:
            PdfReader = libs["pypdf"][0]
            reader = PdfReader(REPORT)
            total = len(reader.pages)
            t = reader.pages[0].extract_text() or ""
            ok_title = TITLE in t
            ok_date = today in t
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (pypdf): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            log(f"pypdf validation failed: {exc}")
    if not ok:
        try:
            info = parse_pdf(data)
            total = count_pages(data, info["entries"], info["pages_num"])
            fp = first_page_num(data, info["entries"], info["pages_num"])
            text = extract_page_text(data, info["entries"], fp) if fp else ""
            ok_title = TITLE in text
            ok_date = today in text
            ok_count = (old_count is None) or (total == old_count + 1)
            log(f"validation (stdlib): pages={total}, title={ok_title}, "
                f"date={ok_date}, count_ok={ok_count}")
            ok = ok_title and ok_date and ok_count
        except Exception as exc:
            traceback.print_exc()
            log(f"stdlib validation failed: {exc}")

    if not ok:
        log("error: cover page validation failed")
        return 1
    log("OK: cover page prepended to report.pdf")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
